style.css:
@-moz-document domain("youtube.com") {
/* =================================
   GLOW RIOT - RAINBOW VIDEO TITLES
   ================================= */

@keyframes glow-riot-home-titles {
  0% {
    color: #ff0000;
    text-shadow: 0 0 8px #ff0000;
  }
  12.5% {
    color: #ff8000;
    text-shadow: 0 0 8px #ff8000;
  }
  25% {
    color: #ffff00;
    text-shadow: 0 0 8px #ffff00;
  }
  37.5% {
    color: #39ff14;
    text-shadow: 0 0 8px #39ff14;
  }
  50% {
    color: #00ffcc;
    text-shadow: 0 0 8px #00ffcc;
  }
  62.5% {
    color: #008cff;
    text-shadow: 0 0 8px #008cff;
  }
  75% {
    color: #a020f0;
    text-shadow: 0 0 8px #a020f0;
  }
  87.5% {
    color: #ff1493;
    text-shadow: 0 0 8px #ff1493;
  }
  100% {
    color: #ff0000;
    text-shadow: 0 0 8px #ff0000;
  }
}

/* Homepage recommended video titles */

ytd-rich-grid-media a#video-title-link,
ytd-rich-grid-media #video-title,
ytd-rich-item-renderer a#video-title-link,
ytd-rich-item-renderer #video-title {
  font-family: "Cosmic Sans", "Comic Sans MS", cursive !important;
  font-weight: 900 !important;
  animation: glow-riot-home-titles 8s steps(1, end) infinite !important;
}


/* ================================
   GLOW RIOT - SIDEBAR DECORATIONS
   ================================ */

/* Sidebar section headings */

ytd-guide-collapsible-section-entry-renderer #header yt-formatted-string {
  font-family: "Comic Sans MS", "Comic Sans", cursive !important;
  color: #ff99e6 !important;
  font-size: 1.3rem !important;
  text-shadow: 0 0 8px rgba(255, 102, 217, 0.8) !important;
}

/* Hearts beside sidebar headings */

ytd-guide-collapsible-section-entry-renderer #header yt-formatted-string::before {
  content: "♡ ";
  color: #cc80ff !important;
}

/* Sidebar links */

ytd-guide-entry-renderer yt-formatted-string.title {
  font-family: "Comic Sans MS", "Comic Sans", cursive !important;
  color: #f5ccff !important;
  letter-spacing: 0.3px !important;
}

/* Stars and hearts beside sidebar links */

ytd-guide-entry-renderer yt-formatted-string.title::before {
  content: "✯ ";
  color: #ff66d9 !important;
}

ytd-guide-entry-renderer yt-formatted-string.title::after {
  content: " ♡";
  color: #b366ff !important;
}

/* Alternating decorations */

ytd-guide-entry-renderer:nth-child(even) yt-formatted-string.title::after {
  content: " ✯";
  color: #ff80df !important;
}

/* Glowing hover effect */

ytd-guide-entry-renderer:hover {
  background: linear-gradient(
    90deg,
    rgba(255, 102, 217, 0.25),
    rgba(153, 51, 255, 0.25)
  ) !important;
  border-radius: 15px !important;
  box-shadow: 0 0 10px rgba(255, 102, 217, 0.4) !important;
  transform: translateX(4px);
  transition: all 0.2s ease-in-out !important;
}

/* Sidebar icons */

ytd-guide-entry-renderer yt-icon {
  color: #ff80df !important;
  filter: drop-shadow(0 0 4px rgba(255, 102, 217, 0.7)) !important;
}
}
